export default function ContactForm() {
  // Server Action defined inline in the Server Component.
  async function submitContact(formData: FormData) {
    'use server'

    const name = formData.get('name')
    const email = formData.get('email')
    const message = formData.get('message')

    // Validate that all fields are provided.
    if (!name || !email || !message) {
      throw new Error('All fields (name, email, and message) are required.')
    }

    const nameStr = String(name).trim()
    const emailStr = String(email).trim()
    const messageStr = String(message).trim()

    if (nameStr.length === 0 || emailStr.length === 0 || messageStr.length === 0) {
      throw new Error('All fields (name, email, and message) are required.')
    }

    // Simulate saving the contact message.
    console.log('Contact message received:', { name: nameStr, email: emailStr, message: messageStr })
  }

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={submitContact}>
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" placeholder="Your name" required />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" placeholder="you@example.com" required />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" placeholder="Your message" required />
        </div>
        <button type="submit">Send Message</button>
      </form>
    </div>
  )
}

